{"metadata":{"kernelspec":{"language":"python","display_name":"Python 3","name":"python3"},"language_info":{"name":"python","version":"3.12.13","mimetype":"text/x-python","codemirror_mode":{"name":"ipython","version":3},"pygments_lexer":"ipython3","nbconvert_exporter":"python","file_extension":".py"},"kaggle":{"accelerator":"nvidiaTeslaT4","dataSources":[{"sourceType":"datasetVersion","sourceId":18410506}],"isInternetEnabled":true,"language":"python","sourceType":"notebook","isGpuEnabled":false}},"nbformat_minor":4,"nbformat":4,"cells":[{"cell_type":"code","source":"import torch \nimport torch.nn as nn\nfrom torch.nn import functional as F\n\nbatch_size = 32\nblock_size = 8\nmax_iterations = 5000\neval_intervals = 500\nlearning_rate = 1e-3\ndevice = torch.device(\"cuda\" if torch.cuda.is_available() else \"cpu\")\neval_iterations = 200\nn_embd = 32\ntorch.manual_seed(1337)\n\nkaggle_input = '/kaggle/input/datasets/mohammedsunain/input-txt/input.txt'\nwith open(kaggle_input, 'r', encoding='utf-8') as f:\n    data = f.read()\n\nchars = sorted(list(set(data)))\nvocab_size = len(chars)\n\ns_to_i = {ch:i for i,ch in enumerate(chars)} # encrypt mapping\ni_to_s = {i:ch for i,ch in enumerate(chars)} # decrypt mapping\n\ndef encode(s):\n    return [s_to_i[c] for c in s]\ndef decode(i):\n    return ''.join([i_to_s[c] for c in i])\n\nencrypted_data = torch.tensor(encode(data), dtype= torch.long)\n\nn = int(0.9*len(encrypted_data))\n\ntrain_data = encrypted_data[:n]\ntest_data = encrypted_data[n:]\n\n# data loading\ndef get_batch(split):\n    data = train_data if split == 'train' else test_data\n\n    ix = torch.randint(len(encrypted_data)-block_size, (batch_size,))\n    x = torch.stack([encrypted_data[i:i+block_size] for i in ix] )\n    y = torch.stack([encrypted_data[i+1:i+block_size+1] for i in ix])\n    x,y = x.to(device), y.to(device)\n    return x,y\n\ndef estimated_loss():\n    out = {}\n    model.eval()\n    for split in ['train', 'val']:\n        losses = torch.zeros(eval_iterations)\n        for k in range(eval_iterations):\n            X,Y = get_batch(split)\n            X, Y = X.to(device), Y.to(device)\n            logits, loss = model(X,Y)\n            losses[k] = loss.item()\n        out[split] = losses.mean()\n    model.train()\n    return out\n\nclass Head(nn.Module):\n    def __init__(self, head_size):\n        super().__init__()\n        self.key = nn.Linear(n_embd, head_size, bias=False)\n        self.query = nn.Linear(n_embd, head_size, bias=False)\n        self.value = nn.Linear(n_embd, head_size, bias=False)\n        self.register_buffer('tril',torch.tril(torch.ones(block_size,block_size)))\n\n    def forward(self,x):\n        B,T,C = x.shape\n        k = self.key(x)\n        q = self.query(x)\n\n        weights = q @ k.transpose (-2,-1) * C**-0.5 # (B,T,16) @ (B,16,T) --> (B,T,T)\n\n# weights = torch.zeros((T,T))\n        weights = weights.masked_fill(self.tril[:T,:T]==0, float('-inf'))\n        weights = F.softmax(weights, dim= -1)\n        v = self.value(x)\n        out = weights@ v\n        return out\n\nclass MultiHeadAttention(nn.Module):\n    \"\"\"multiple heads of self-attention in parallel\"\"\"\n\n    def __init__(self,num_heads, head_size):\n        super().__init__()\n        self.heads = nn.ModuleList([Head(head_size) for _ in range(num_heads)])\n        self.proj = nn.Linear(n_embd, n_embd)\n\n    def forward(self,x):\n        out = torch.cat([h(x) for h in self.heads], dim = -1)\n        out = self.proj(out)\n        return out\n\nclass FeedForward(nn.Module):\n    def __init__(self, n_embd):\n        super().__init__()\n        self.net = nn.Sequential(\n            nn.Linear(n_embd,n_embd * 4),\n            nn.ReLU(),\n            nn.Linear(4 * n_embd,n_embd),  \n        )\n    def forward(self,x):\n        return self.net(x)\n\nclass Block(nn.Module):\n    \"\"\"Transformer block: communication followed by computation \"\"\"\n    def __init__(self, n_embd, n_head):    \n        super().__init__()\n        head_size = n_embd//n_head\n        self.sa = MultiHeadAttention(n_head, head_size)\n        self.ffwd = FeedForward(n_embd)\n\n    def forward(self,x):\n        x = x + self.sa(x)\n        x = x + self.ffwd(x)\n        return x\n\n\n# super simple bigram model\nclass bigramLanguageModel(nn.Module):\n    def __init__(self):\n        super().__init__()\n        self.token_embedding_table = nn.Embedding(vocab_size,n_embd)\n        self.position_embd_table = nn.Embedding(block_size, n_embd)\n        self.blocks = nn.Sequential(\n            Block(n_embd, n_head=4),\n            Block(n_embd, n_head=4),\n            Block(n_embd, n_head=4),\n        )\n        self.lm_head = nn.Linear(n_embd, vocab_size)\n\n    def forward(self, idx, targets = None):\n        B,T = idx.shape\n\n        tok_emb = self.token_embedding_table(idx) # B T C\n        pos_emb =  self.position_embd_table(torch.arange(T, device=idx.device))\n        x = tok_emb + pos_emb\n        x = self.blocks(x)\n        logits = self.lm_head(x) # B T vocab_size\n\n        \n        if targets is None:\n            loss = None\n        else:\n            B, T, C = logits.shape\n            logits = logits.view(B*T, C)\n            targets = targets.view(B*T)\n            loss = F.cross_entropy(logits, targets)\n        return logits, loss\n\n    def generate(self, idx, max_new_tokens):# idx is (B,T) array of indices\n        for _ in range(max_new_tokens):\n            idx_cond = idx[:, -block_size:]\n            # get the prediction\n            logits, loss = self(idx_cond)\n            # focus only on the last step\n            logits = logits[:,-1,:]# (B,C)\n            # apply softmax for probabilities\n            prob = F.softmax(logits, dim= -1)\n            # sample from the distribution\n            idx_next = torch.multinomial(prob, num_samples=1)\n            # append sampled index to the running sequence\n            idx = torch.cat((idx, idx_next), dim=1) # (B, T+1)\n        return idx\n\n    \n\nmodel = bigramLanguageModel()\nmodel = model.to(device)\n# create a pytorch optimizer \noptimizer= torch.optim.Adam(model.parameters(), lr=1e-3)\n\nfor iters in range(max_iterations):\n    if iters % eval_intervals == 0:\n        losses = estimated_loss()\n        print(f\"step {iters}: train loss{losses['train']:.4f}, val loss {losses['val']:.4f}\")\n\n    xb, yb = get_batch('train')\n    xb, yb = xb.to(device), yb.to(device)\n\n    logits, loss = model(xb, yb)\n    optimizer.zero_grad(set_to_none=True)\n    loss.backward()\n    optimizer.step()\n\ncontext = torch.zeros((1,1) ,dtype=torch.long).to(device)\nprint(decode(model.generate(context, max_new_tokens=500)[0].tolist()))","metadata":{"_uuid":"b1115754-1cfa-4d9f-9634-25c46078650d","_cell_guid":"4e265895-9cb5-4e3e-b304-f75a6d2ae7db","trusted":true,"collapsed":false,"jupyter":{"outputs_hidden":false},"execution":{"iopub.status.busy":"2026-07-28T14:51:34.650961Z","iopub.execute_input":"2026-07-28T14:51:34.651712Z","iopub.status.idle":"2026-07-28T14:53:17.489711Z","shell.execute_reply.started":"2026-07-28T14:51:34.651682Z","shell.execute_reply":"2026-07-28T14:53:17.488767Z"}},"outputs":[{"name":"stdout","text":"step 0: train loss4.6185, val loss 4.6269\nstep 500: train loss2.3972, val loss 2.3945\nstep 1000: train loss2.2420, val loss 2.2432\nstep 1500: train loss2.1968, val loss 2.1984\nstep 2000: train loss2.1481, val loss 2.1519\nstep 2500: train loss2.1173, val loss 2.1009\nstep 3000: train loss2.0689, val loss 2.0712\nstep 3500: train loss2.0483, val loss 2.0517\nstep 4000: train loss2.0181, val loss 2.0134\nstep 4500: train loss2.0146, val loss 2.0064\n\nCANG OUKE VINCESTESTA:\nFare to\nbaise my beour:\nYou OFanst:\nClatause:\nWanthien wice, to bardetlahsanes wice my fef'st to zount:\nYou someeffition!\n\nVOLUCKENTEA:\nWhitheers, hand latisel drovent, and to poman is wace!\n\nAULIUS:\nVall thume courver:\nSuperais's, why mole mausent\nTo this dest my like to that\nmoakinson have I basten themourive with in his so more for under of thrupt for are my tomef't teying our whiped\nWith my of.\n\nHENNLANUS:\nNoblian\nSadsal these her, hoin cour aaranny RICH smoof' thee wi\n","output_type":"stream"}],"execution_count":14}]}